head.script:
scwin.gAcptNo;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {

};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name txb_ISUR_CD_onfocus
 * @description txb_ISUR_CD 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onfocus = function() {
    try {
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF90320.txb_ISUR_CD_onfocus" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onblur
 * @description txb_ISUR_CD 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_ISUR_CD.getValue() === "") {
            txb_COM_NM.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF90320.txb_ISUR_CD_onblur" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onkeyup
 * @description txb_ISUR_CD 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onkeyup = function() {
    try {
        if (txb_ISUR_CD.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF90320.txb_ISUR_CD_onkeyup" });
    }
};

/**
 * @method
 * @name btn_ISUR_CD_onclick
 * @description btn_ISUR_CD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_ISUR_CD_onclick = function() {
    try {
        $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM); // 법인명 검색 팝업
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF90320.btn_ISUR_CD_onclick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            $c.cm.fn_com_Confirm_set();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF90320.Grd_com_isur_OnKeyPress" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    try {
        $c.cm.fn_com_Confirm_set();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF90320.Grd_com_isur_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF90320.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF90320.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF90320.Grd_com_isur_OnKillFocus" });
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else {
            return true;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF90320.MxDataSet_com_isur_OnFilter" });
    }
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    try {
        const vTp = cmb_PeriodTp.getValue();
        $c.stf.setFromToDate(vTp, edt_SDATE, edt_EDATE); // 기간선택 콤보박스
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF90320.cmb_PeriodTp_onselchange" });
    }
};

/**
 * @method
 * @name btn_EDATE_onclick
 * @description btn_EDATE 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_EDATE_onclick = function() {
    try {
        popUpCalendar2(edt_EDATE); // 공시일자-시작일 이미지 버튼 클릭 시 달력 팝업
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF90320.btn_EDATE_onclick" });
    }
};

/**
 * @method
 * @name btn_SDATE_onclick
 * @description btn_SDATE 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_SDATE_onclick = function() {
    try {
        popUpCalendar2(edt_SDATE); // 공시일자-종료일 이미지 버튼 클릭 시 달력 팝업
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF90320.btn_SDATE_onclick" });
    }
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        // 클릭된 값 변수에 셋팅
        scwin.setContnId(row);
        if (colid === "ACPT_NO") {
            await scwin.openDisclViewerK(scwin.gAcptNo, "R"); // (정정)공시일 컬럼 더블클릭시 관련 보고서 뷰잉

        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF90320.grd_Grid_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Search_onclick = function() {
    try {
        scwin.search(); // 조회 버튼
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF90320.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadCompleted
 * @description dts_Grid 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page); // 총 건수
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF90320.dts_Grid_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave('ULDSTF25300.gfm', SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_Grid, {fileName: "메타추출모니터링", type: "2"}); // 엑셀 다운로드
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF90320.btn_Excel_onclick" });
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setCode
 * @description 공시일자, 팀, 담당자 세팅
 * @returns {void}
 * @hidden N
 */
scwin.setCode = function() {
    //  기간 from~ to  셋팅(공시일자)
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SDATE.setValue($c.ut.cGetToday("yyyymmdd"));
    edt_EDATE.setValue(vCurDate); // 현재날짜

};

/**
 * @method
 * @name search
 * @description 조회 버튼
 * @returns {void}
 * @hidden N
 */
scwin.search = function() {
    let url = "/listingCommon.do?method=listGeneral" + "&outputMessageId=DISCLS_EXTRC_INFO_MONITOR_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.dsclstat.select.meta.formextr.monitor" + "&{P}param01=" + rdo_MKT_ID.getValue() + "&{P}param02=" + rdo_MKT_ID.getValue() + "&{P}param03=" + txb_ISUR_CD.getValue() + // 법인코드
        "&{P}param04=" + txb_ISUR_CD.getValue() + // 법인코드
        "&{P}param05=" + edt_SDATE.getValue() + "&{P}param06=" + edt_EDATE.getValue() + "&{P}param07=" + txb_FORM_CD.getValue() + "&{P}param08=" + txb_FORM_CD.getValue() + "&{P}param09=" + rdo_Extr_Yn.getValue() + "&{P}param10=" + rdo_Extr_Yn.getValue() + "&{P}param11=" + rdo_Extr_Yn.getValue() + "&SCREN_ID=" + 'ULDSTF25300.gfm' + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Grid.DataID = encodeURI(url);

    dts_Grid.Reset();
};

/**
 * @method
 * @name setContnId
 * @description 그리드에서 클릭 row의 변수셋팅
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    scwin.gAcptNo = dts_Grid.getCellData(Number(obj), "ACPT_NO");
};

/**
 * @method
 * @name openDisclViewerK
 * @description open Discl Viewer K 처리
 * @param {*} pAcptNo pAcptNo
 * @param {*} pViewerStat pViewerStat
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDisclViewerK = async function(pAcptNo, pViewerStat) {
    let vHttp;
    if (js_svrGubun.indexOf("test") > -1) {
        vHttp = g_test_stf_url;
    } else if (js_svrGubun === "dev" || js_svrGubun === 'local') {
        vHttp = g_dev_stf_url;
    } else {
        vHttp = g_real_stf_url;
    }
    let url = vHttp + "/dsclproc/ULDSTF10001.gfm?" + "gAcptNo=" + pAcptNo + "&gViewerStat=" + pViewerStat + "&frameID=" + frame.FrameID + "&gAccssAuthTpCd=01" + "&screnID=" + 'ULDSTF25300.gfm';
    const winTitle = "공시뷰어";
    if ($c.frame.path("/top") !== undefined) {

        $c.frame.path("/top").WinOpen_child("viewer" + pAcptNo, url, winTitle, 1000, 800);
    } else {
        await $c.frame.CreateFrame("viewer" + pAcptNo, url, winTitle, 10, 10, 1000, 800, "window", 0, 0, true);
    }
};

/**
 * @method
 * @name gform_onload
 * @description gform onload 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.gform_onload = function() {
    $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM); // 법인코드 및 법인명(회사명) 관련
    Grd_com_isur.style.zIndex = 30;
    $c.libRoundPanel.PanelToGroupBox(panel_1); // 검색조건 패널에 스타일 적용

    scwin.setCode(); // 공시일자(from~to)
    scwin.init(); // 시장구분

    scwin.search();
};
